/* Token Launch Radar — dark theme. One accent, one warning colour, hairline borders, tabular numbers. */
:root {
  --canvas: #0b0f14;
  --surface: #111826;
  --surface-2: #16202f;
  --ink: #e8eef5;
  --muted: #93a3b5;
  --faint: #5d6f83;
  --border: #22304a;
  --accent: #4ade80;
  --accent-dim: #1d3a2a;
  --gold: #f5c451;
  --negative: #f87171;
  --positive: #4ade80;
  --radius: 10px;
  --font-body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-num: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, monospace;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 15px/1.55 var(--font-body);
}
.wrap { max-width: 1180px; margin: 0 auto; padding: 0 20px; }
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; }
h1 { font-size: 27px; font-weight: 700; }
h2 { font-size: 19px; font-weight: 650; margin-bottom: 8px; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
code { font-family: var(--font-num); font-size: 0.92em; color: var(--gold); }

/* Header */
.site-head { border-bottom: 1px solid var(--border); background: linear-gradient(180deg, #101827, var(--canvas)); }
.site-head .wrap { display: flex; flex-wrap: wrap; gap: 18px 40px; align-items: center; justify-content: space-between; padding-top: 22px; padding-bottom: 20px; }
.brand { display: flex; gap: 14px; align-items: center; }
.brand-mark {
  width: 38px; height: 38px; border-radius: 50%; flex: none;
  background:
    radial-gradient(circle at 50% 50%, var(--accent) 0 3px, transparent 4px),
    conic-gradient(from 210deg, transparent 0 300deg, var(--accent-dim) 300deg 360deg),
    radial-gradient(circle, transparent 0 12px, var(--accent-dim) 13px 14px, transparent 15px),
    radial-gradient(circle, transparent 0 18px, #24405c 19px 20px, transparent 21px);
  border: 1px solid var(--border);
}
.tagline { color: var(--muted); font-size: 13.5px; margin-top: 2px; }
.tagline strong { color: var(--gold); font-family: var(--font-num); font-weight: 600; }
.head-stats { display: flex; gap: 26px; margin: 0; flex-wrap: wrap; }
.head-stats div { min-width: 86px; }
.head-stats dt { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--faint); }
.head-stats dd { margin: 1px 0 0; font-family: var(--font-num); font-size: 19px; font-weight: 600; }

/* Tabs */
.tabs { display: flex; gap: 6px; padding-top: 16px; }
.tab {
  background: transparent; border: 1px solid transparent; border-radius: 999px;
  padding: 7px 16px; color: var(--muted); cursor: pointer; font-weight: 550;
}
.tab:hover { color: var(--ink); }
.tab.is-active { background: var(--surface-2); border-color: var(--border); color: var(--ink); }

/* Views */
.view { display: none; padding: 18px 0 8px; }
.view.is-active { display: block; }
.view-note { color: var(--muted); max-width: 78ch; margin-bottom: 14px; }

/* Controls */
.controls { display: flex; flex-wrap: wrap; gap: 10px; align-items: end; margin-bottom: 10px; }
.ctl { display: flex; flex-direction: column; gap: 4px; font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--faint); }
.ctl input, .ctl select {
  background: var(--surface); border: 1px solid var(--border); border-radius: 8px;
  padding: 8px 10px; font-size: 14px; text-transform: none; letter-spacing: 0; color: var(--ink); min-height: 38px;
}
.ctl input:focus, .ctl select:focus { outline: 2px solid var(--accent-dim); border-color: var(--accent); }
.ctl-search { flex: 1 1 210px; }
.ctl-search input { width: 100%; }
.result-line { color: var(--muted); font-size: 13px; margin-bottom: 8px; font-family: var(--font-num); }

/* Tables */
.table-scroll { overflow-x: auto; border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface); }
table.board { border-collapse: collapse; width: 100%; min-width: 860px; }
.board th, .board td { padding: 9px 10px; text-align: left; white-space: nowrap; }
.board td.chains { max-width: 198px; overflow: hidden; text-overflow: ellipsis; }
.board td.cat { max-width: 148px; overflow: hidden; text-overflow: ellipsis; }
.board thead th {
  font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--faint);
  border-bottom: 1px solid var(--border); background: var(--surface-2); position: sticky; top: 0;
}
.board tbody tr { border-bottom: 1px solid #1a2639; cursor: pointer; }
.board tbody tr:last-child { border-bottom: none; }
.board tbody tr:hover { background: #16233a; }
.board tbody tr.is-selected { background: var(--accent-dim); }
.board td.num, .board th.num { text-align: right; font-family: var(--font-num); }
.board td.rank { color: var(--faint); }
.board td.name { font-weight: 600; white-space: normal; min-width: 150px; }
.board td .sub { display: block; font-weight: 400; color: var(--faint); font-size: 12px; font-family: var(--font-num); }
.board td.cat, .board td.chains { color: var(--muted); font-size: 13.5px; }
.pos { color: var(--positive); }
.neg { color: var(--negative); }
.badge {
  display: inline-block; padding: 1px 8px; border-radius: 999px; font-size: 11.5px; font-weight: 600;
  border: 1px solid var(--border); color: var(--muted);
}
.badge.watch { color: #0b0f14; background: var(--gold); border-color: var(--gold); }
.badge.early { color: var(--accent); border-color: var(--accent-dim); background: rgba(74, 222, 128, 0.07); }
.delta { font-family: var(--font-num); font-size: 12px; margin-left: 6px; }
.delta.up { color: var(--positive); }
.delta.down { color: var(--negative); }

/* Detail */
.detail {
  margin-top: 14px; border: 1px solid var(--border); border-radius: var(--radius);
  background: var(--surface); padding: 20px 22px;
}
.detail-head { display: flex; flex-wrap: wrap; gap: 8px 18px; align-items: baseline; justify-content: space-between; }
.detail-head h2 { font-size: 22px; }
.detail-head .implied { font-family: var(--font-num); font-size: 22px; color: var(--accent); font-weight: 700; }
.detail-head .implied small { display: block; font-size: 11px; color: var(--faint); text-transform: uppercase; letter-spacing: 0.07em; text-align: right; }
.fact-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 10px 18px; margin: 16px 0; }
.fact-grid dt { font-size: 11px; text-transform: uppercase; letter-spacing: 0.07em; color: var(--faint); }
.fact-grid dd { margin: 1px 0 0; font-family: var(--font-num); font-size: 15px; }
.factors { display: grid; gap: 8px; margin: 6px 0 18px; }
.factor { display: grid; grid-template-columns: 168px 1fr 74px; gap: 12px; align-items: center; font-size: 13.5px; }
.factor .fname { color: var(--muted); }
.factor .fval { font-family: var(--font-num); text-align: right; }
.factor .track { height: 8px; border-radius: 4px; background: #0d1420; border: 1px solid #1a2639; overflow: hidden; }
.factor .fill { height: 100%; background: linear-gradient(90deg, #2c7a4b, var(--accent)); }
.factor .fill.warn { background: linear-gradient(90deg, #8a6d1f, var(--gold)); }
.farm { margin: 0; padding-left: 22px; display: grid; gap: 10px; }
.farm li { line-height: 1.5; }
.farm li::marker { color: var(--accent); font-family: var(--font-num); }
.detail h3 { font-size: 15px; margin: 14px 0 8px; color: var(--ink); }
.detail-close { float: right; background: none; border: 1px solid var(--border); border-radius: 8px; padding: 4px 12px; color: var(--muted); cursor: pointer; }
.detail-close:hover { color: var(--ink); }

/* Sandbox */
.sandbox { margin-top: 26px; border: 1px dashed var(--border); border-radius: var(--radius); padding: 18px 22px; background: rgba(22, 32, 47, 0.45); }
.sandbox-note { color: var(--muted); max-width: 88ch; }
.linklike { background: none; border: none; color: var(--accent); cursor: pointer; padding: 0; text-decoration: underline; }
.sliders { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); gap: 16px 26px; margin-top: 14px; }
.slider { display: grid; gap: 4px; font-weight: 550; font-size: 14px; }
.slider output { font-family: var(--font-num); color: var(--gold); font-weight: 600; margin-left: 6px; }
.slider input[type="range"] { width: 100%; accent-color: var(--accent); }
.slider-hint { font-weight: 400; color: var(--faint); font-size: 12.5px; }

/* Model view */
.formula {
  font-family: var(--font-num); font-size: 14.5px; background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 16px 20px; margin-bottom: 16px; overflow-x: auto; white-space: nowrap; color: var(--ink);
}
.formula .hl { color: var(--accent); }
.explain-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 14px; margin-bottom: 22px; }
.explain-card { border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface); padding: 16px 18px; }
.explain-card h3 { font-size: 15px; margin-bottom: 6px; color: var(--accent); }
.explain-card p { color: var(--muted); font-size: 14px; }

/* Footer */
.site-foot { border-top: 1px solid var(--border); margin-top: 34px; }
.site-foot .wrap { padding-top: 16px; padding-bottom: 26px; }
.site-foot p { color: var(--faint); font-size: 13px; max-width: 92ch; }

@media (max-width: 640px) {
  .factor { grid-template-columns: 118px 1fr 62px; }
  .head-stats { gap: 16px; }
  h1 { font-size: 23px; }
}
